{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The close analogue [11C]13, sharing the biaryl carboxamide core, showed excellent brain permeability in rats (SUVmax 3.6), demonstrating that this core can be CNS-penetrant when the polar succinimide is replaced by a lipophilic fused ring.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The moderately similar [11C]5i, a carboxamide with a fluoro-methoxyphenyl group and heteroarylmethoxy substituent, reached >1 SUV in mouse brain, supporting meaningful CNS access for the query's heteroarylmethyl-piperidine variant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The tetrahydroisoquinoline [11C]MC80, which shares the arylmethyl-substituted fused piperidine motif, showed high initial brain uptake in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The related tetrahydroisoquinoline [11C]MC113 with a biaryl substituent showed high brain uptake in mice, supporting the CNS permeability of this fused-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The structurally similar KOR radiotracer 18F-LY2459989, containing carboxamide, fluoro-methoxyphenyl, piperidine, and pyridine motifs, exhibited high brain uptake in nonhuman primates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The closest analogue QCA showed limited brain uptake (0.42 %ID/g) in mice, indicating that the shared biaryl carboxamide core can be associated with poor CNS access when combined with a polar succinimide side chain.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite the closest QCA analogue showing poor brain uptake, the query replaces the polar succinimide with a fused basic piperidine and methoxy-pyridylmethyl substituent, aligning it with multiple structurally related CNS radiotracers that show high-to-moderate brain permeability; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain uptake, plasma, or CSF measurement for the exact query molecule.",
    "Efflux transporter liability was not directly assessed; the basic piperidine could be a P-gp substrate.",
    "The closest analogue QCA is poor, but its key structural liability is absent in the query, limiting direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

